<form id="property-form" hidden><h3 id="editor-title">Novo imóvel</h3><input name="id" type="hidden"><div class="form-grid"><label class="full">Título<input name="title" required maxlength="90"></label><label>Tipo<select name="type"><option>Casa</option><option>Apartamento</option><option>Terreno</option></select></label><label>Bairro<input name="neighborhood" required maxlength="60"></label><label class="full">Rua<input name="street" required maxlength="100"></label><label>Preço (R$)<input name="price" type="number" required min="1" max="999999999" step="0.01"></label><label>Área (m²)<input name="area" type="number" required min="1" max="1000000" step="0.1"></label><label>Quartos<input name="beds" type="number" required min="0" max="100" value="0"></label><label>Banheiros<input name="baths" type="number" required min="0" max="100" value="0"></label><label>Vagas<input name="parking" type="number" required min="0" max="100" value="0"></label><label>Status<select name="status"><option value="published">Publicado</option><option value="draft">Rascunho</option></select></label><label class="full">Descrição<textarea name="description" rows="4" required maxlength="3000"></textarea></label><label class="full">Fotos do imóvel<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple><small>Até 8 fotos, com até 5 MB cada. Novas fotos substituem a galeria atual.</small></label><div id="photo-preview" class="photo-preview full"></div><label class="check-label full"><input name="featured" type="checkbox"> Destacar este imóvel</label></div><div class="form-actions"><button class="button" type="submit">Salvar imóvel</button><button type="button" class="button outline" id="cancel-edit">Cancelar</button></div></form>
